//! Compare synthetic restore handoff model against eight retained native rows.
use spore_core::cell_restore_wrapper_handoff_v1::{project,Action,RefId};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn id(x:Option<RefId>)->u32{match x{None=>0,Some(RefId::Input)=>1,Some(RefId::Candidate)=>2,Some(RefId::OldInput)=>3,Some(RefId::OldCandidate)=>4}}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native stdout")).unwrap();assert_eq!(b.len(),160);for i in 0..8{let k=i%4;let cw=if i>=4{0x37f}else{0x27f};let old=match k{2=>(Some(RefId::Input),Some(RefId::Candidate)),3=>(Some(RefId::OldInput),Some(RefId::OldCandidate)),_=>(None,None)};let x=project(old.0,old.1,k!=0,cw,0x1f80,true).unwrap();let mut events=0;for a in x.actions{events=(events<<4)|match a{Action::Retain(_)=>1,Action::Release(_)=>2,Action::Reject{..}=>3};}let row=&b[i*20..(i+1)*20];assert_eq!((w(row,0),w(row,4),w(row,8)),(id(x.input_slot),id(x.candidate_slot),events));let fp=w(row,12);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,16)&!0x3f,0x1f80);}println!("matched eight retained restore handoff rows; synthetic callbacks and lifetimes admitted");}
